get_product_page.code:
const response = await client.productPage.getProductPage();
const settings = response.map.product_page;
console.log(settings.configuration.details.display_description);
console.log(settings.quick_view.product_quick_view);

patch_product_page.code:
const response = await client.productPage.patchProductPage({
    product_page: {configuration: {details: {display_description: true}}, up_sell: {short_description: true}},
});
const settings = response.map.product_page;
console.log(settings.configuration.details.display_description, settings.up_sell.short_description);

get_product_page_section.code:
const response = await client.productPage.getProductPageSection('quick_view');
const quickView = response.map.product_page.quick_view;
console.log(quickView.product_quick_view, quickView.display_add_to_cart_button);
